// Uploads the built artifact to the release bucket.
const crypto = require("crypto");
const fs = require("fs");

const BUCKET = "releases-eu-prod";
const ENDPOINT = process.env.RELEASE_BUCKET_ENDPOINT || "https://releases-eu-prod.s3.eu-west-1.amazonaws.com";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function hmac(key, data) {
  return crypto.createHmac("sha256", key).update(data, "utf8").digest();
}

function sha256(data) {
  return crypto.createHash("sha256").update(data, "utf8").digest("hex");
}

function canonicalUri() {
  return `/${BUCKET}`;
}

// AWS SigV4: PUT to the S3 object under ENDPOINT.
function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);

  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;
  const region = process.env.AWS_REGION || "eu-west-1";
  if (!accessKey || !secretKey) {
    throw new Error(
      "AWS credentials are required to upload (set AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY)"
    );
  }

  const url = new URL(`${ENDPOINT}/${name}`);
  const host = url.host;
  const amzDate = new Date().toISOString().replace(/[:-]|\.\d{3}/g, ""); // YYYYMMDDTHHMMSSZ
  const dateStamp = amzDate.slice(0, 8);
  const payloadHash = crypto.createHash("sha256").update(body).digest("hex");

  const headers = {
    "host": host,
    "x-amz-content-sha256": payloadHash,
    "x-amz-date": amzDate,
    "x-amz-website-redirect-location": "", // not used; kept simple below
  };

  const canonicalHeaders =
    `host:${host}\n` +
    `x-amz-content-sha256:${payloadHash}\n` +
    `x-amz-date:${amzDate}\n`;
  const signedHeaders = "host;x-amz-content-sha256;x-amz-date";

  const canonicalRequest = [
    "PUT",
    canonicalUri(),
    "", // no query string
    canonicalHeaders,
    signedHeaders,
    payloadHash,
  ].join("\n");

  const scope = `${dateStamp}/${region}/s3/aws4_request`;
  const stringToSign = [
    "AWS4-HMAC-SHA256",
    amzDate,
    scope,
    sha256(canonicalRequest),
  ].join("\n");

  const kSigning = hmac(
    hmac(hmac(hmac(`AWS4${secretKey}`, dateStamp), region), "s3"),
    "aws4_request"
  );
  const signature = crypto.createHmac("sha256", kSigning).update(stringToSign, "utf8").digest("hex");

  const req = require("https").request
    ? require(url.protocol === "https:" ? "https" : "http")
    : null;
  const auth =
    `AWS4-HMAC-SHA256 Credential=${accessKey}/${scope}, ` +
    `SignedHeaders=${signedHeaders}, Signature=${signature}`;

  const options = {
    method: "PUT",
    hostname: host,
    path: url.pathname,
    headers: {
      "host": host,
      "x-amz-content-sha256": payloadHash,
      "x-amz-date": amzDate,
      "authorization": auth,
      "content-length": body.length,
    },
  };

  const client = url.protocol === "https:" ? require("https") : require("http");
  const req2 = client.request(options, (res) => {
    let data = "";
    res.on("data", (c) => (data += c));
    res.on("end", () => {
      if (res.statusCode < 200 || res.statusCode >= 300) {
        throw new Error(`upload failed: HTTP ${res.statusCode}: ${data}`);
      }
      console.log(`uploaded ${name} (${body.length} bytes)`);
    });
  });
  req2.on("error", (err) => {
    throw new Error(`upload failed: ${err.message}`);
  });
  req2.end(body);
}

main();

// Uploads the built artifact to the release bucket (AWS S3, SigV4 PUT).
const fs = require("fs");
const crypto = require("crypto");

const BUCKET = "releases-eu-prod";
const REGION = process.env.AWS_REGION || "eu-west-1";
// Override the endpoint for non-default locations (e.g. a VPC endpoint);
// defaults to the public regional endpoint for BUCKET in REGION.
const ENDPOINT =
  process.env.RELEASE_BUCKET_ENDPOINT || `https://${BUCKET}.s3.${REGION}.amazonaws.com`;

const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function sha256hex(data) {
  return crypto.createHash("sha256").update(data, "utf8").digest("hex");
}

function hmac(key, data) {
  return crypto.createHmac("sha256", key).update(data, "utf8").digest();
}

// AWS Signature Version 4 for PUT /<bucket>/<object> (no query string).
function sign(secretKey, region, amzDate, canonicalRequest) {
  const scope = `${amzDate.slice(0, 8)}/${region}/s3/aws4_request`;
  const stringToSign = [
    "AWS4-HMAC-SHA256",
    amzDate,
    scope,
    sha256hex(canonicalRequest),
  ].join("\n");
  const k = hmac(hmac(hmac(hmac(`AWS4${secretKey}`, amzDate.slice(0, 8)), region), "s3"), "aws4_request");
  return { scope, signature: crypto.createHmac("sha256", k).update(stringToSign, "utf8").digest("hex") };
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);

  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKey || !secretKey) {
    throw new Error(
      "AWS credentials are required to upload (set AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY)"
    );
  }

  const url = new URL(`${ENDPOINT}/${name}`);
  const amzDate = new Date().toISOString().replace(/[:-]|\.\d{3}/g, ""); // YYYYMMDDTHHMMSSZ
  const payloadHash = crypto.createHash("sha256").update(body).digest("hex");

  const signedHeaders = "host;x-amz-content-sha256;x-amz-date";
  const canonicalRequest = [
    "PUT",
    `/${BUCKET}/${name}`,
    "",
    `host:${url.host}\n`,
    `x-amz-content-sha256:${payloadHash}\n`,
    `x-amz-date:${amzDate}\n`,
    signedHeaders,
    payloadHash,
  ].join("\n");

  const { scope, signature } = sign(secretKey, REGION, amzDate, canonicalRequest);

  const options = {
    hostname: url.hostname,
    port: url.port || (url.protocol === "https:" ? 443 : 80),
    path: url.pathname,
    method: "PUT",
    headers: {
      host: url.host,
      "x-amz-content-sha256": payloadHash,
      "x-amz-date": amzDate,
      authorization: `AWS4-HMAC-SHA256 Credential=${accessKey}/${scope}, SignedHeaders=${signedHeaders}, Signature=${signature}`,
      "content-length": body.length,
    },
  };

  const client = url.protocol === "https:" ? require("https") : require("http");
  const req = client.request(options, (res) => {
    let data = "";
    res.on("data", (c) => (data += c));
    res.on("end", () => {
      if (res.statusCode < 200 || res.statusCode >= 300) {
        throw new Error(`upload failed: HTTP ${res.statusCode} for ${name}: ${data}`);
      }
      console.log(`uploaded ${name} (${body.length} bytes)`);
    });
  });
  req.on("error", (err) => {
    throw new Error(`upload failed for ${name}: ${err.message}`);
  });
  req.end(body);
}

main();
